INSERT INTO work (id, owner_id, title, description, origin_kind, creation_type, revision, deleted_episode_revision, created_at, slug, author_name, theme, hook, hanja, hero_line1, hero_line2, hero_background) VALUES
('138eef13-65a9-5ec7-bd54-6202e922c01d', 'b09cdf87-6901-50df-9c76-881c81f4f034', '추락한 천재 배우가 회귀했다', '> 여덟 살에는 천재 아역이었다.  
> 스물두 살에는 인성이 나쁜 배우가 되었고,  
> 서른넷에는 이름보다 얼굴이 먼저 기억나는 단역이 되었다.  
>   
> 한서준은 오랫동안 자신의 인생을 망친 사람들을 원망했다.  
>   
> 다시 돌아온 오디션장.  
>   
> 감독이 물었다.  
>   
> “준비한 연기를 보여 주시겠어요?”  
>   
> 서준은 대본을 덮었다.  
> 이번에는 잘 보이기 위해 연기하지 않을 생각이었다.

천재 아역의 몰락, 회귀, 인성 논란의 진실, 악덕 소속사, 미래의 흥행작 선점, 오디션 역전, 무명 감독과의 동반 성공, 천재 라이벌, 팬덤 형성, 광고와 예능, 연기대상과 영화제라는 익숙한 장치를 사용하는 장편 연예계물이다.

주인공은 배우다.

아이돌과 가수, 방송인, 제작자도 등장하지만 서사의 중심은 작품 선택과 연기, 촬영 현장과 커리어의 성장에 둔다. 방송사와 소속사, 작품과 시상식은 모두 가상 설정으로 구성한다.

판타지 장치는 단 한 번의 회귀다.

상태창이나 대본의 흥행 점수를 보여 주는 능력은 없다. 주인공은 미래의 성공작을 일부 기억하지만, 같은 작품에 같은 결과가 따라온다고 확신할 수는 없다.

그가 되찾아야 하는 것은 인기만이 아니다.

타인의 평가에 자신을 전부 맡기지 않으면서도, 관객에게 무언가를 전달하는 배우로 살아가는 방법이다.

---', 'original', 'original', 0, 0, '2026-11-09T00:00:00Z', 'genre-template-entertainment', '장르 템플릿 샘플', 'star', '', NULL, NULL, NULL, NULL)
